532:       // Where it does exist, it should only become visible once the
533:       // marquee has actually settled into its page-load entrance position
534:       // — not fade in progressively together with the block's own
535:       // opacity. Starting its alpha at 0 (same color, fully transparent)
536:       // keeps the logos' own fade-in untouched; the instant that entrance
537:       // tween below actually completes, a separate eased tween fades the
538:       // border's alpha back up to its real 0.10 (see the onComplete
539:       // below) instead of snapping it back on instantly.
540:       if (isDesktop) gsap.set(logos, { borderTopColor: 'hsla(0,0%,0%,0)' });
541:     }
542:     if (ctaLink) gsap.set(ctaLink, { autoAlpha: 0 });
543:     if (isDesktop) {
544:       gsap.set(motionWrapper, { width: '100vw', height: '100vh', right: 'auto', bottom: 'auto', willChange: 'width, height' });
545:     }
546: 
547:     var dims = { vw: 100, vh: 100 };
548: 
549:     var tl = gsap.timeline({ defaults: { ease: 'power2.out' } });
550: 
551:     tl.to(motionWrapper, { autoAlpha: 1, duration: 0.5 });
552: 
553:     if (isDesktop) {
554:       tl.to(dims, {
555:         vw: 60, vh: 82, duration: 1.3, ease: 'power2.inOut',
556:         onUpdate: function () { motionWrapper.style.width = dims.vw + 'vw'; motionWrapper.style.height = dims.vh + 'dvh'; },
557:         onComplete: function () { motionWrapper.style.willChange = 'auto'; }
558:       });
559:     }
560: 
561:     if (isDesktop) {
562:       if (logos) {
563:         tl.to(logos, {
564:           autoAlpha: 1, y: 0, duration: 0.65,
565:           onComplete: function () {
566:             gsap.to(logos, { borderTopColor: 'hsla(0,0%,0%,0.10)', duration: 0.5, ease: 'power2.out' });
567:           }
568:         });
569:       }
570: 
571:       if (split) {
572:         tl.to(split.words, { autoAlpha: 1, y: 0, duration: 0.5, stagger: 0.08 });
573:       } else if (headingEl) {
574:         tl.to(headingEl, { autoAlpha: 1, y: 0, duration: 0.5 });
575:       }
576: 
577:       if (lines.length) {
578:         tl.to(lines, { autoAlpha: 1, y: 0, duration: 0.55, stagger: 0.15 });
579:       }
580:     } else if (isMobile) {
581:       // Heading wipe-reveal and the logos sliding up run together, mirroring
582:       // how both progress across the same Figma storyboard frames rather
583:       // than one strictly waiting for the other to finish.
584:       tl.addLabel('reveal');
585:       if (headingEl) {
586:         tl.to(headingEl, { clipPath: 'inset(0% 0% 0% 0%)', duration: 0.9, ease: 'power2.inOut' }, 'reveal');
587:       }
588:       if (logos) {
589:         tl.to(logos, { autoAlpha: 1, y: 0, duration: 0.7 }, 'reveal+=0.1');
590:       }
591:     }
592: 
593:     // Entrance finished (desktop): release the scroll lock now that the
594:     // pinned scroll-driven phase below is about to exist and can manage
595:     // scroll on its own.
596:     tl.eventCallback('onComplete', function () {
597:       if (isDesktop) {
598:         clearTimeout(scrollLockSafety);
599:         unlockScroll();
600:       }
601: 
602:       // Phase 5 (scroll-driven, desktop only): magenta panel drags off-screen
603:       // (transform, no resize); the message block moves+grows to the hero's
604:       // center via transform too. Each line's shift from "left-aligned" to
605:       // "centered within the block" is measured once and tweened continuously
606:       // (per line, since each line is a different width) instead of toggling
607:       // text-align/align-items instantly. The CTA link keeps sliding into its
608:       // centered spot the whole time but STAYS INVISIBLE until the right
609:       // block's text (contentWrap + its lines) actually finishes that
610:       // position tween — only then does it fade in (see the textPositioned
611:       // label below), so it never appears before the text is done centering.
612:       // Because contentWrap itself is scaling up (1 -> 1.35) to grow the
613:       // paragraph text, the CTA link is also a child of it and would visually
614:       // grow along with it unless compensated — an onUpdate continuously sets
615:       // the CTA's own scale to the exact reciprocal of contentWrap's live
616:       // scale, so its rendered size stays fixed (the 14px token from the
617:       // "link" class) throughout the whole scrub, never inheriting the
618:       // parent's growth. Nothing snaps mid-scroll.
619:       if (isDesktop && window.ScrollTrigger && messageWrapper && contentWrap && lines.length) {
620:         var mwRect = messageWrapper.getBoundingClientRect();
621:         var cwRect = contentWrap.getBoundingClientRect();
622:         var lineRects = lines.map(function (l) { return l.getBoundingClientRect(); });
623:         var ctaRect = ctaLink ? ctaLink.getBoundingClientRect() : null;
624: 
625:         var targetLeft = mwRect.left + (mwRect.width - cwRect.width) / 2;
626:         var targetTop  = mwRect.top + (mwRect.height - cwRect.height) / 2;
627:         var deltaX = targetLeft - cwRect.left;
628:         var deltaY = targetTop - cwRect.top;
629: 
630:         var lineDeltas = lineRects.map(function (r) {
631:           return (cwRect.width - r.width) / 2 - (r.left - cwRect.left);
632:         });
633:         var ctaDelta = ctaRect ? (cwRect.width - ctaRect.width) / 2 - (ctaRect.left - cwRect.left) : 0;
634: 
635:         gsap.set(contentWrap, { transformOrigin: 'center center' });
636:         gsap.set(lines, { transformOrigin: 'center center' });
637:         if (ctaLink) gsap.set(ctaLink, { transformOrigin: 'center center' });
638: 
639:         var scrollTl = gsap.timeline({
640:           defaults: { ease: 'none', duration: 1 },
641:           scrollTrigger: {
642:             trigger: hero,
643:             start: 'top top',
644:             end: '+=100%',
645:             scrub: 1,
646:             pin: true
647:           }
648:         });
649: 
650:         scrollTl.to(motionWrapper, { xPercent: -100 }, 0);
651:         scrollTl.to(messageWrapper, { xPercent: -75 }, 0);
652:         scrollTl.to(contentWrap, {
653:           x: deltaX, y: deltaY, scale: 1.35,
654:           onUpdate: function () {
655:             if (ctaLink) {
656:               var liveScale = gsap.getProperty(contentWrap, 'scale');
657:               gsap.set(ctaLink, { scale: liveScale ? 1 / liveScale : 1 });
658:             }
659:           }
660:         }, 0);
661:         lines.forEach(function (l, i) {
662:           scrollTl.to(l, { x: lineDeltas[i] }, 0);
663:         });
664:         // The right block's text (contentWrap + its lines) finishes its
665:         // position tween at t=1 — this label marks exactly that moment.
666:         // The CTA link keeps sliding into place the whole time (invisible),
667:         // but only becomes visible right here, once that position
668:         // animation has actually completed.
669:         scrollTl.addLabel('textPositioned', 1);
670:         if (ctaLink) {
671:           scrollTl.to(ctaLink, { x: ctaDelta }, 0);
672:           scrollTl.to(ctaLink, { autoAlpha: 1, duration: 0.15 }, 'textPositioned');
673:         }
674:       }
675:     });
676: 
677:     return function () {
678:       if (isDesktop) {
679:         clearTimeout(scrollLockSafety);
680:         unlockScroll();
681:       }
682:       motionWrapper.style.width = '';
683:       motionWrapper.style.height = '';
684:       motionWrapper.style.right = '';
685:       motionWrapper.style.bottom = '';
686:       motionWrapper.style.willChange = '';
687:       motionWrapper.style.transform = '';
688:       if (headingEl) headingEl.style.clipPath = '';
689:       if (logos) { gsap.killTweensOf(logos); logos.style.borderTopColor = ''; }
690:       if (messageWrapper) messageWrapper.style.transform = '';
691:       if (contentWrap) contentWrap.style.transform = '';
692:       if (lines.length) lines.forEach(function (l) { l.style.transform = ''; });
693:       if (ctaLink) ctaLink.style.transform = '';
694:       if (split) split.revert();
695:     };
696:   });
697: });
698: </script>
