101:   --spacing-xs:0.25rem;
102:   --spacing-sm:0.5rem;
103:   --spacing-md:0.75rem;
104:   --spacing-xl:1rem;
105:   --spacing-2xl:1.5rem;
106:   --spacing-3xl:2rem;
107:   --spacing-4xl:2.5rem;
108:   --spacing-5xl:3.5rem;
