113:   --border-radius-sm:4px;
114:   --border-radius-md:6px;
115:   --border-radius-lg:8px;
116:   --border-radius-xl:12px;
117:   --border-radius-2xl:16px;
118:   --border-radius-3xl:20px;
119:   --border-radius-full:9999px;
120: }
